 enum class DspKind:uint8_t{Next,Invalidate,Write};explicit ControllerVoiceFinalSequence(uint32_t patch):patch_(patch){transpose_.emplace(patch);}bool complete()const{return stage_==5;}bool awaitingDsp()const{return transpose_?transpose_->child()==T::Child::Dsp:scale_?scale_->child()==S::Child::Dsp:finish_&&finish_->awaitingDsp();}uint32_t word()const{return transpose_?transpose_->word():scale_?scale_->word():finish_?finish_->word():0;}DspKind dspKind()const{if(!finish_)return DspKind::Next;auto s=finish_->stage();return s==ZS::AwaitCommit?DspKind::Invalidate:(s==ZS::AwaitMode||s==ZS::AwaitLevel)?DspKind::Write:DspKind::Next;}uint16_t dspAddress()const{return finish_&&finish_->stage()==ZS::AwaitMode?0x8026:0x8029;}bool resumeDsp(){if(!awaitingDsp())return false;bool ok=transpose_?transpose_->resumeChild():scale_?scale_->resumeChild():finish_->resumeDsp();if(ok)selectNext();return ok;}
