 template<class R,class W>unsigned advanceBefore(unsigned budget,R&&read,W&&write,int previous=-1){auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;if(voice_){V::Credits c{3,7};auto used=voice_->advanceBefore(cost,c,[&](){return read(0xd023,1,cost);});if(voice_->complete()){auto a=voice_->address();voice_.reset();if(transpose_)transpose_->resumeChild(a);else scale_->resumeChild(a);}return used;}if(floating_){if(!floating_->advance())return 0;if(floating_->complete()){auto v=floating_->result();floating_.reset();convert_->resumeChild(v);selectNext();}return cost;}uint32_t a=0;unsigned width=0;bool wr=false;access(a,width,wr);auto mem=width?bus(a,width,wr?previous:-1):0;if(transpose_){T::Credits c{mem,10};auto used=transpose_->advanceBefore(cost,c,[&](T::Access f)->uint32_t{if(f==T::Access::WriteOffset||f==T::Access::WriteNote){write(a&0xffffff,transpose_->writeValue(),1,cost);return 0;}return read(a&0xffffff,width,cost);});if(transpose_->child()==T::Child::Voice)voice_.emplace();selectNext();return used;}if(override_){O::Credits c{mem};auto used=override_->advanceBefore(cost,c,[&](O::Read){return read(a&0xffffff,width,cost);});selectNext();return used;}if(convert_){C::Credits c{mem,10};auto used=convert_->advanceBefore(cost,c,[&](bool){return read(a&0xffffff,width,cost);});if(convert_->child()==C::Child::Float)floating_.emplace(convert_->input());return used;}if(scale_){auto s=scale_->stage();S::Credits c{(s==SS::PushUnscaled||s==SS::PopUnscaled)?2u:mem,10};auto used=scale_->advanceBefore(cost,c,[&](S::Access f)->uint32_t{return f==S::Access::Stack?converted_:read(a&0xffffff,width,cost);});if(scale_->child()==S::Child::Voice)voice_.emplace();selectNext();return used;}Z::Credits c{mem,finish_->stage()==ZS::Return?7u:10u};auto used=finish_->advanceBefore(cost,c,[&](Z::Read){return read(a&0xffffff,width,cost);});selectNext();return used;}
