 void selectNext(){if(transpose_&&transpose_->complete()){transpose_.reset();++stage_;override_.emplace(patch_);}else if(override_&&override_->complete()){auto v=override_->value();override_.reset();++stage_;convert_.emplace(v);}else if(convert_&&convert_->complete()){converted_=convert_->converted();convert_.reset();++stage_;scale_.emplace(patch_,converted_);}else if(scale_&&scale_->complete()){scale_.reset();++stage_;finish_.emplace(patch_);}else if(finish_&&finish_->complete()){finish_.reset();++stage_;}}
 static unsigned bus(uint32_t a,unsigned n,int p){unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((p&1)||x!=uint32_t(p|1))c+=x<0x400000?3:1;p=int(x);}else{c+=x>=0xffffa0?1:3;p=-1;}}return c;}
